var i=`0123-olivier-salad`;var n=`world-0123`;var a=`RU`;var r=`eastern-europe`;var s=4;var o=52;var l={en:`Olivier Salad`,ua:`Салат олів'є`};var g={en:`A classic dish from Russia, featuring potato, carrot, chicken egg, smoked ham. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Росія. Основні складники: картопля, морква, куряче яйце, копчена шинка. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`potato`,360,`g`],[`carrot`,220,`g`],[`water`,900,`ml`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,4,`pcs`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:12,i:[[`smoked-ham`,240,`g`],[`fermented-cucumber`,220,`g`],[`canned-green-peas`,200,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:6,i:[[`mayonnaise`,250,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var c={slug:i,id:n,country:`RU`,region:r,servings:4,minutes:52,title:l,text:g,steps:d};export{a as country,c as default,n as id,o as minutes,r as region,s as servings,i as slug,d as steps,g as text,l as title};